{
 "id": "w2-gouv-09",
 "edition": "",
 "inst": "Région",
 "verdict": "bad",
 "transpo": "forte",
 "dateISO": "2025-12-18",
 "villeKey": "Utrecht",
 "pays": "NL",
 "theme":   { "fr": "Gouvernance — accessibilité numérique du guichet communal", "nl": "Bestuur — digitale toegankelijkheid van het gemeenteloket", "en": "Governance — digital accessibility of the municipal service portal" },
 "matiere": { "key": "gouvernance", "fr": "Gouvernance et digitalisation", "nl": "Bestuur en digitalisering", "en": "Governance and digitalisation" },
 "titre": {
   "fr": "Utrecht : plainte fondée sur des documents en ligne inaccessibles aux personnes handicapées, et dix mois de conversations sans plan",
   "nl": "Utrecht: gegronde klacht over onlinedocumenten die ontoegankelijk zijn voor mensen met een handicap, en tien maanden gesprekken zonder plan",
   "en": "Utrecht: complaint upheld over online documents inaccessible to disabled people, and ten months of talks without a plan"
 },
 "ville": {
   "fr": "Utrecht — Pays-Bas, commune d'Utrecht et ombudsman d'Utrecht",
   "nl": "Utrecht — Nederland, gemeente Utrecht en ombudsman Utrecht",
   "en": "Utrecht — Netherlands, City of Utrecht and the Utrecht Ombudsman"
 },
 "date": {
   "fr": "18 décembre 2025 (rapport de l'ombudsman d'Utrecht)",
   "nl": "18 december 2025 (rapport van de ombudsman Utrecht)",
   "en": "18 December 2025 (report of the Utrecht Ombudsman)"
 },
 "competence": {
   "fr": "Région — pouvoirs locaux, qualité et accessibilité des services numériques publics ; ministre chargé des Pouvoirs locaux et de la Transition numérique",
   "nl": "Gewest — lokale besturen, kwaliteit en toegankelijkheid van digitale overheidsdiensten; minister bevoegd voor Lokale Besturen en Digitale Transitie",
   "en": "Region — local government, quality and accessibility of public digital services; minister responsible for Local Government and Digital Transition"
 },
 "quoi": {
   "fr": "Un habitant a déposé le 16 février 2025 une plainte contre la commune d'Utrecht au motif que les documents PDF publiés sur le site communal ne respectent pas les obligations légales d'accessibilité numérique pour les personnes ayant une déficience visuelle, auditive ou cognitive. La commune a reconnu la plainte fondée le 19 mai 2025, mais n'a ensuite proposé ni mesure concrète ni calendrier : de juin à septembre 2025, les réponses sont restées au stade de la discussion, et en novembre 2025 il n'existait toujours aucun plan. L'ombudsman d'Utrecht a rendu son rapport le 18 décembre 2025.",
   "nl": "Een inwoner diende op 16 februari 2025 een klacht in tegen de gemeente Utrecht omdat de pdf-documenten op de gemeentelijke website niet voldoen aan de wettelijke verplichtingen inzake digitale toegankelijkheid voor mensen met een visuele, auditieve of cognitieve beperking. De gemeente verklaarde de klacht gegrond op 19 mei 2025, maar stelde daarna geen concrete maatregel of tijdlijn voor: van juni tot september 2025 bleven de antwoorden bij gesprekken, en in november 2025 bestond er nog altijd geen plan. De ombudsman Utrecht bracht zijn rapport uit op 18 december 2025.",
   "en": "On 16 February 2025 a resident complained against the City of Utrecht on the ground that PDF documents published on the municipal website do not meet the legal digital accessibility requirements for people with visual, hearing or cognitive impairments. The city upheld the complaint on 19 May 2025 but then offered neither concrete measures nor a timetable: from June to September 2025 responses remained at the discussion stage, and by November 2025 there was still no plan. The Utrecht Ombudsman issued its report on 18 December 2025."
 },
 "resultats": {
   "fr": "L'ombudsman conclut que la plainte est fondée parce que la commune n'agit pas concrètement, et écrit que « la commune n'offre aucune perspective dans ses réponses aux questions », alors même qu'elle reconnaît le problème. Près de dix mois se sont écoulés entre le dépôt de la plainte et le rapport, sans progrès mesurable. Trois recommandations sont formulées : élaborer un plan d'action avec objectifs et échéances pour la mise en conformité des PDF, ou invoquer formellement l'exception de charge disproportionnée ; clore les plaintes par des engagements concrets ou des délais clairs ; désigner une personne de contact si les améliorations promises ne se matérialisent pas.",
   "nl": "De ombudsman besluit dat de klacht gegrond is omdat de gemeente niet concreet handelt, en schrijft dat « de gemeente in de beantwoording van de vragen geen perspectief biedt », terwijl ze het probleem wel erkent. Er verstreken bijna tien maanden tussen de klacht en het rapport, zonder meetbare voortgang. Er zijn drie aanbevelingen: een actieplan met doelen en deadlines voor de pdf-conformiteit opstellen, of formeel de uitzondering van onevenredige last inroepen; klachten afsluiten met concrete verbintenissen of duidelijke termijnen; een contactpersoon aanduiden als de beloofde verbeteringen uitblijven.",
   "en": "The ombudsman concludes the complaint is justified because the city takes no concrete action, writing that 'the municipality offers no perspective in its answers to the questions', even though it acknowledges the problem. Nearly ten months elapsed between the complaint and the report, with no measurable progress. Three recommendations follow: draw up an action plan with goals and deadlines for PDF compliance, or formally invoke the disproportionate burden exemption; close complaints with concrete commitments or clear deadlines; designate a contact person if promised improvements fail to materialise."
 },
 "transposabilite": {
   "fr": "L'accessibilité numérique des sites publics découle d'une directive européenne transposée en Belgique, et s'applique donc aux sites régionaux et communaux bruxellois ainsi qu'à leurs formulaires en ligne. Ce qui bloquerait : les déclarations d'accessibilité existent souvent sur le papier sans audit indépendant, et les documents PDF joints échappent en pratique aux contrôles. Ce qui serait directement réalisable : faire auditer par un tiers les principaux formulaires et documents des guichets numériques régionaux, publier le résultat et un calendrier de correction, et tenir un registre public des plaintes d'accessibilité et de leur suite.",
   "nl": "De digitale toegankelijkheid van overheidswebsites volgt uit een Europese richtlijn die in België is omgezet, en geldt dus voor de Brusselse gewestelijke en gemeentelijke sites en hun onlineformulieren. Wat zou blokkeren: toegankelijkheidsverklaringen bestaan vaak op papier zonder onafhankelijke audit, en bijgevoegde pdf-documenten ontsnappen in de praktijk aan controle. Wat direct haalbaar is: de belangrijkste formulieren en documenten van de gewestelijke digitale loketten door een derde laten auditeren, het resultaat en een correctiekalender publiceren, en een openbaar register bijhouden van toegankelijkheidsklachten en hun opvolging.",
   "en": "Digital accessibility of public websites stems from a European directive transposed in Belgium, and therefore applies to Brussels regional and municipal sites and their online forms. What would block: accessibility statements often exist on paper without independent audit, and attached PDF documents in practice escape checks. Directly feasible: have a third party audit the main forms and documents of regional digital services, publish the result and a remediation timetable, and keep a public register of accessibility complaints and their follow-up."
 },
 "angle": {
   "fr": "Le ministre chargé des Pouvoirs locaux et de la Transition numérique peut-il faire auditer par un tiers indépendant l'accessibilité des principaux formulaires et documents des guichets numériques régionaux, et publier le résultat avec un calendrier de correction ?",
   "nl": "Kan de minister bevoegd voor Lokale Besturen en Digitale Transitie de toegankelijkheid van de belangrijkste formulieren en documenten van de gewestelijke digitale loketten door een onafhankelijke derde laten auditeren, en het resultaat met een correctiekalender publiceren?",
   "en": "Can the minister responsible for Local Government and Digital Transition have an independent third party audit the accessibility of the main forms and documents of regional digital services, and publish the result with a remediation timetable?"
 },
 "sources": [
   { "media": "Ombudsman Utrecht (rapport)", "date": "18/12/2025", "url": "https://utrechtsombudsloket.nl/wp-content/uploads/2026/03/Rapport-Ombudsman-Utrecht-Gegronde-klacht-en-dan.pdf" }
 ]
}
